const INDEX_HTML = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#17131f\">\n<title>Philosophes — Top Trumps</title>\n<style>\n:root{\n  --bg:#15111b;--bg2:#21182a;--ink:#241b28;--cream:#f5ead2;--cream2:#ead9b7;\n  --gold:#d6a847;--gold2:#9b6b25;--plum:#37263e;--plum2:#241a2b;--line:#5e4a64;\n  --muted:#c9bdc8;--star:#d7a63b;--boat:#466f83;--logic:#7d77a5;--fire:#bd5845;--social:#5f826e;\n}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 18% 8%,#4a3655 0,#211824 34%,#100d13 78%);color:#fbf4e7;font-family:ui-rounded,\"Avenir Next\",system-ui,-apple-system,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #78677f;border-radius:14px;padding:13px 17px;background:#2c2232;color:#fff;font-weight:850;letter-spacing:.025em}.primary{background:linear-gradient(135deg,#e0b65f,#aa772c);border-color:#f0cc7f;color:#22170c}.ghost{background:transparent}.compact{padding:8px 12px;font-size:.78rem}.hidden{display:none!important}.screen{display:none;min-height:100vh;padding:24px 18px}.screen.active{display:flex}.hero{flex-direction:column;align-items:center;justify-content:center;text-align:center}.brand{font-family:Georgia,serif;font-size:clamp(3.2rem,12vw,7rem);font-weight:900;letter-spacing:-.05em;color:#f1d59c;text-shadow:0 3px 0 #664720}.subtitle{letter-spacing:.42em;margin:8px 0 18px;color:#d3a85a}.tagline{max-width:720px;color:#cfc5d4}.actions{display:grid;gap:12px;width:min(440px,100%);margin-top:24px}.panel{margin:auto;align-self:center;flex-direction:column;gap:16px;width:min(520px,100%);min-height:auto;background:rgba(35,28,43,.96);border:1px solid #6f5c7b;border-radius:28px;padding:26px;box-shadow:0 24px 60px #0008}.wide{width:min(680px,100%)}label{display:grid;gap:7px;color:#d8cfe0;font-weight:700}input,select{width:100%;padding:13px;border-radius:12px;border:1px solid #6d5c78;background:#151119;color:#fff}.code-input{text-transform:uppercase;letter-spacing:.28em;text-align:center;font-size:1.35rem}.eyebrow{font-size:.72rem;letter-spacing:.2em;color:#b89dca}.room-code{font-size:3rem;font-weight:900;letter-spacing:.16em;color:#f0cf8d}.player-list{display:grid;gap:9px}.player-row,.score-chip{display:flex;justify-content:space-between;gap:10px;padding:11px 13px;background:#18131d;border-radius:12px;border:1px solid #44384c}.muted{color:#aaa0b0}\n.game-screen{display:none!important;flex-direction:column;gap:12px}.game-screen.active{display:flex!important}.gamebar{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;background:#17121b;border:1px solid #493d52;border-radius:14px;padding:11px 14px}.scoreboard{display:flex;gap:8px;overflow:auto;padding-bottom:2px}.score-chip{white-space:nowrap}.score-chip.me{border-color:#d8ac58}.gamegrid{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(360px,.98fr);gap:20px;align-items:start;max-width:1320px;width:100%;margin:0 auto}\n/* CARTE GAUCHE : illustration + faits uniquement */\n.philo-card{background:var(--cream);color:var(--ink);border:6px solid var(--gold2);border-radius:25px;overflow:hidden;box-shadow:0 22px 58px #0009;min-width:0}.portrait{height:clamp(360px,52vh,610px);background:linear-gradient(145deg,#e7c879 0,#d1a45b 42%,#8b668a 100%);position:relative;border-bottom:4px solid #7e5a2a}.portrait::after{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 35% 24%,#fff4 0,transparent 42%),linear-gradient(180deg,transparent 60%,#271c3130);pointer-events:none}.portrait img{width:100%;height:100%;object-fit:cover;display:block;position:relative;z-index:1}.portrait-placeholder{height:100%;display:grid;place-items:center;text-align:center;padding:30px;font-family:Georgia,serif;font-size:1.25rem;font-weight:900;letter-spacing:.08em;color:#35283b;background:linear-gradient(135deg,#f2d78f,#b8868f)}.portrait-placeholder small{display:block;margin-top:8px;font-family:system-ui;font-size:.72rem;letter-spacing:.16em;opacity:.72}.identity{padding:18px 20px 9px}.identity-top{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.identity h1{font-family:Georgia,serif;font-size:clamp(2rem,4.6vw,3.2rem);line-height:.96;margin:0;letter-spacing:-.04em}.identity .dates{margin:7px 0 0;color:#695b65;font-size:1rem}.current{align-self:flex-start;background:#4d3b55;color:#fff;padding:7px 11px;border-radius:999px;font-size:.76rem;white-space:nowrap}.fact-grid{display:grid;grid-template-columns:1fr;gap:8px;padding:10px 20px 14px}.fact{display:grid;grid-template-columns:110px 1fr;gap:10px;border-top:1px solid #cbb792;padding-top:9px}.fact b{font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:#8a652c}.fact span{font-size:.92rem;color:#514650}.quote{margin:0 20px 20px;padding:14px 16px;border-left:4px solid var(--gold);background:#edddbd;border-radius:0 12px 12px 0;font-family:Georgia,serif;font-size:1.02rem;line-height:1.35}.quote small{display:block;margin-top:8px;color:#756672;font-family:system-ui;font-size:.76rem}\n/* PANNEAU DROIT : seule zone des scores/commentaires */\n.playpanel{background:linear-gradient(180deg,rgba(51,38,58,.98),rgba(29,22,34,.98));border:1px solid #725e78;border-radius:24px;padding:18px;position:sticky;top:12px;box-shadow:0 20px 50px #0006}.phase{margin:0 0 13px;font-size:1rem;color:#eadfeb}.category-buttons{display:grid;gap:10px}.cat-btn{--cat:#7b6a86;width:100%;display:grid;grid-template-columns:48px minmax(0,1fr) 64px;gap:4px 12px;align-items:center;text-align:left;padding:12px 13px;border-radius:15px;border:1px solid color-mix(in srgb,var(--cat) 70%,#fff 15%);background:linear-gradient(90deg,color-mix(in srgb,var(--cat) 42%,#211827),#221a29 66%);box-shadow:inset 4px 0 0 var(--cat);transition:transform .12s ease,border-color .12s ease,filter .12s ease}.cat-btn:hover:not(:disabled){transform:translateY(-1px);filter:brightness(1.08)}.cat-btn:disabled{opacity:.6;cursor:default}.cat-icon{grid-row:1/3;width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:#f9edd8;color:#291e2c;font-size:1.45rem;font-weight:950}.cat-title{font-size:1rem;line-height:1.05}.cat-comment{font-size:.78rem;line-height:1.25;color:#e2d8e3;font-weight:500}.cat-score{grid-column:3;grid-row:1/3;align-self:center;justify-self:end;font-family:Georgia,serif;font-size:2rem;font-style:normal;font-weight:900;color:#fff}.cat-btn[data-cat=\"Notoriété\"]{--cat:var(--star)}.cat-btn[data-cat=\"Aventure\"]{--cat:var(--boat)}.cat-btn[data-cat=\"Rationalité\"]{--cat:var(--logic)}.cat-btn[data-cat=\"Radicalité\"]{--cat:var(--fire)}.cat-btn[data-cat=\"Impact socio-culturel\"]{--cat:var(--social)}.masked-score{filter:blur(8px);user-select:none}.reveal-grid{display:grid;gap:10px}.reveal-card{display:grid;grid-template-columns:1fr auto;gap:3px 10px;padding:12px;background:#17121b;border:1px solid #4a3d54;border-radius:12px}.reveal-card span{font-size:.8rem;color:#aaa0b0}.reveal-card strong{grid-column:2;grid-row:1/3;font-size:2rem}.reveal-card.winner{border-color:#d1a34c;box-shadow:inset 0 0 0 1px #d1a34c}.leave{align-self:flex-end}dialog{max-width:560px;border:1px solid #7f6a8c;border-radius:20px;background:#211a28;color:#fff;padding:24px}dialog::backdrop{background:#000b}\n@media(max-width:900px){.gamegrid{grid-template-columns:1fr}.playpanel{position:static}.portrait{height:min(58vh,520px)}.screen{padding:12px 9px}.philo-card{border-width:4px}.identity h1{font-size:2.2rem}.fact{grid-template-columns:90px 1fr}.cat-btn{grid-template-columns:44px minmax(0,1fr) 55px}.cat-score{font-size:1.7rem}}\n@media(max-width:520px){.portrait{height:48vh;min-height:300px}.identity{padding:15px 15px 8px}.fact-grid{padding:8px 15px 12px}.quote{margin:0 15px 15px}.current{font-size:.68rem}.cat-comment{font-size:.74rem}.playpanel{padding:12px}}\n\n.cat-btn{position:relative;overflow:hidden;border-color:rgba(0,0,0,.16)!important}\n.cat-btn::before{content:'';position:absolute;inset:0;background:var(--cat-color);opacity:.96;z-index:0}\n.cat-btn>*{position:relative;z-index:1}\n.cat-icon{display:grid;place-items:center;width:54px;height:54px;color:#111;background:rgba(255,255,255,.18);border-radius:12px;flex:0 0 54px}\n.cat-icon svg{width:40px;height:40px;display:block}\n.cat-btn .cat-title,.cat-btn .cat-comment,.cat-btn .cat-score{color:#111!important}\n.cat-btn[data-cat=\"Notoriété\"]{--cat-color:#8B24FF}\n.cat-btn[data-cat=\"Aventure\"]{--cat-color:#55D5EE}\n.cat-btn[data-cat=\"Rationalité\"]{--cat-color:#FFF33E}\n.cat-btn[data-cat=\"Radicalité\"]{--cat-color:#FF2854}\n.cat-btn[data-cat=\"Impact socio-culturel\"]{--cat-color:#25EFA0}\n\n\n.uber-toggle{padding:11px 13px;border:1px solid #6d5c78;border-radius:12px;background:#18131d}.uber-toggle span{display:flex;align-items:center;color:#fff}.uber-toggle small{font-weight:500;color:#aaa0b0}.timer-pill{display:inline-grid;place-items:center;min-width:44px;height:34px;border-radius:999px;background:#f2d991;color:#24180d;font-weight:950;font-size:1.15rem}.timer-pill.urgent{background:#ff5a65;color:#fff}.power-panel{margin:0 0 12px;padding:12px;border:1px solid #806a8c;border-radius:15px;background:#17121b}.power-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.charges{font-weight:950;letter-spacing:.12em;color:#f3cf69}.power-btn{margin-top:9px;width:100%;background:linear-gradient(135deg,#6c2ca8,#a84acb);border-color:#cb8de7}.effect-banner{margin:0 0 12px;padding:11px 13px;border-radius:13px;background:#4b245b;border:1px solid #b879cc}.effect-banner b{color:#f1ce69}.power-choice,.peek-panel{margin:0 0 12px;padding:12px;border-radius:13px;background:#151119;border:1px solid #5c4967}.choice-cards{display:grid;gap:8px}.choice-card{width:100%;text-align:left}.peek-row{display:grid;grid-template-columns:1fr repeat(5,auto);gap:7px;font-size:.72rem;padding:6px 0;border-top:1px solid #33283b}.status-effects{font-size:.72rem;color:#d8c9dc;margin-top:5px}.cat-btn.power-disabled{opacity:.45}.fake-score{font-style:italic}.own-cat{margin:8px 0;padding:9px;border:1px dashed #927da0;border-radius:11px}.own-cat button{padding:7px 9px;margin:3px;font-size:.72rem}\n\n.power-btn{\n  width:62px!important;height:62px!important;min-width:62px!important;\n  padding:0!important;margin:10px auto 3px!important;border-radius:50%!important;\n  display:grid!important;place-items:center!important;\n  background:#f3cf69!important;color:#18131d!important;border:3px solid #18131d!important;\n  box-shadow:0 0 0 3px #f3cf69,0 5px 0 #18131d!important;\n  font-size:30px!important;line-height:1!important;font-weight:950!important;\n}\n.power-btn:hover{transform:translateY(-1px)}\n.power-btn:active{transform:translateY(3px);box-shadow:0 0 0 3px #f3cf69,0 2px 0 #18131d!important}\n.power-hint{text-align:center;font-size:.72rem;color:#d8c9dc;margin-top:7px}\n\n</style>\n</head>\n<body>\n<main>\n<section id=\"home\" class=\"screen active hero\"><div class=\"brand\">PHILOSOPHES</div><div class=\"subtitle\">TOP TRUMPS</div><p class=\"tagline\">Notoriété · Aventure · Rationalité · Radicalité · Impact socio-culturel</p><div class=\"actions\"><button id=\"createBtn\" class=\"primary\">CRÉER UNE PARTIE</button><button id=\"joinBtn\">REJOINDRE UNE PARTIE</button><button id=\"rulesBtn\" class=\"ghost\">RÈGLES</button></div></section>\n<section id=\"create\" class=\"screen panel\"><h1>Créer une partie</h1><label>Votre nom<input id=\"hostName\" maxlength=\"24\" placeholder=\"Socrate\"></label><label>Mode<select id=\"gameMode\"><option value=\"classic\">Classique</option><option value=\"blind\">À l’aveugle</option><option value=\"superblind\">Super aveugle</option></select></label><label class=\"uber-toggle\"><span><input id=\"ubermensch\" type=\"checkbox\" style=\"width:auto;margin-right:9px\"> Mode Übermensch</span><small>Atouts · 3 charges par joueur · un seul atout par manche</small></label><label>Joueurs<select id=\"maxPlayers\"><option>2</option><option>3</option><option selected>4</option><option>5</option><option>6</option></select></label><button id=\"confirmCreate\" class=\"primary\">CRÉER LA SALLE</button><button data-screen=\"home\" class=\"ghost\">RETOUR</button></section>\n<section id=\"join\" class=\"screen panel\"><h1>Rejoindre</h1><label>Votre nom<input id=\"joinName\" maxlength=\"24\" placeholder=\"Diogène\"></label><label>Code de salle<input id=\"roomCodeInput\" maxlength=\"6\" class=\"code-input\" placeholder=\"ABC123\"></label><button id=\"confirmJoin\" class=\"primary\">REJOINDRE</button><button data-screen=\"home\" class=\"ghost\">RETOUR</button></section>\n<section id=\"lobby\" class=\"screen panel wide\"><div class=\"eyebrow\">CODE DE LA SALLE</div><div id=\"roomCode\" class=\"room-code\">—</div><button id=\"copyCode\" class=\"ghost compact\">COPIER LE CODE</button><p id=\"modeLabel\"></p><div id=\"playerList\" class=\"player-list\"></div><p id=\"lobbyStatus\" class=\"muted\"></p><button id=\"startOnlineGame\" class=\"primary hidden\">LANCER LA PARTIE</button><button id=\"leaveLobby\" class=\"ghost\">QUITTER</button></section>\n<section id=\"game\" class=\"screen game-screen\"><header class=\"gamebar\"><span id=\"turnLabel\"></span><strong id=\"leaderLabel\"></strong><span id=\"timerLabel\" class=\"timer-pill\">10</span><span id=\"potLabel\"></span></header><div id=\"scoreboard\" class=\"scoreboard\"></div><div class=\"gamegrid\"><article id=\"myCard\" class=\"philo-card\"></article><aside class=\"playpanel\"><p id=\"phaseMessage\" class=\"phase\"></p><div id=\"effectBanner\" class=\"effect-banner hidden\"></div><div id=\"powerPanel\" class=\"power-panel hidden\"></div><div id=\"powerChoice\" class=\"power-choice hidden\"></div><div id=\"peekPanel\" class=\"peek-panel hidden\"></div><div id=\"waitingChoice\"><div id=\"categoryButtons\" class=\"category-buttons\"></div></div><div id=\"revealBox\" class=\"hidden\"><h2 id=\"revealTitle\"></h2><div id=\"revealGrid\" class=\"reveal-grid\"></div><p id=\"roundResult\"></p><button id=\"nextRound\" class=\"primary hidden\">SUIVANT</button></div></aside></div><button id=\"leaveGame\" class=\"ghost compact leave\">QUITTER</button></section>\n<section id=\"winner\" class=\"screen panel\"><div class=\"eyebrow\">VICTOIRE</div><h1 id=\"winnerName\">—</h1><button id=\"winnerHome\" class=\"primary\">RETOUR À L’ACCUEIL</button></section>\n</main>\n<dialog id=\"rulesDialog\"><h2>Règles</h2><p>Le leader choisit une catégorie. Tous les joueurs révèlent alors le score correspondant. Le meilleur score remporte le pli et devient leader.</p><p>En mode à l’aveugle, les scores sont cachés avant le choix, mais les commentaires restent visibles à droite.</p><p>En mode Super aveugle, avant le choix, seuls une citation et un fait marquant sont visibles. Le nom, l’illustration, les dates, le pays, le courant, les œuvres, les commentaires et les scores sont cachés.</p><p>En cas d’égalité, les cartes restent dans une cagnotte et seuls les joueurs à égalité rejouent pour la remporter.</p><button id=\"closeRules\" class=\"primary\">FERMER</button><p><b>Übermensch :</b> chaque joueur possède 3 charges ⚡. Certaines cartes ont un atout signalé par une icône ⚡. Seuls les non-leaders peuvent cliquer dessus pendant les 10 secondes de choix ; le premier clic reçu par le serveur joue l’atout et révèle son nom. Certaines cartes rares rechargent +1 ⚡, sans dépasser 3.</p></dialog>\n<script src=\"/socket.io/socket.io.js\">\n</script>\n<script>(()=>{\nlet CATS=[];const socket=io();let state=null;let prevPhase=null;let timerTick=null;let identity=JSON.parse(localStorage.getItem('philoIdentityV2')||'null');\n\nconst START_SOUND='data:audio/mpeg;base64,';\nconst startAudio=new Audio(START_SOUND);\nstartAudio.preload='auto';\nfunction playStartSound(){\n  try{startAudio.currentTime=0;startAudio.play().catch(()=>{})}catch(e){}\n}\nconst $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]));\nconst ICONS={\n'Notoriété':{svg:`<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M32 2l4.5 17L49 7 44 24l17-5-14 11 15 2-15 2 14 11-17-5 5 17-12.5-12L32 62l-4.5-17L15 57l5-17-17 5 14-11-15-2 15-2L3 19l17 5-5-17 12.5 12z\"/></svg>`,color:'#8B24FF'},\n'Aventure':{svg:`<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M11 39h42l-5 8H17zM19 18h19v17H19zM39 19l11 8-11 8zM17 16h2v21h-2z\"/><path d=\"M10 50c5-3 9-3 14 0s9 3 14 0 9-3 14 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M13 41l8 8M20 41l8 8M27 41l8 8M34 41l8 8M41 41l8 8\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg>`,color:'#55D5EE'},\n'Rationalité':{svg:`<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"38\" r=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"/><circle cx=\"32\" cy=\"11\" r=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M31 15L20 54M33 15l11 39M24 31h16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\"/></svg>`,color:'#FFF33E'},\n'Radicalité':{svg:`<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M34 4c3 10-6 13-2 22 2 4 6 4 9 0 1 8 8 10 8 20 0 10-8 16-17 16-10 0-18-7-18-17 0-10 7-16 12-22 1 7 5 9 8 7 4-3 1-10 0-26zm-3 31c1 5-4 7-4 12 0 4 3 7 7 7s7-3 7-7c0-5-4-8-5-12-1 3-2 5-5 5-2 0-3-2-3-5-1 2-2 4-2 6 0 5 2 8 5 8-4-3-4-8 0-14z\"/></svg>`,color:'#FF2854'},\n'Impact socio-culturel':{svg:`<svg viewBox=\"0 0 64 64\" aria-hidden=\"true\"><circle cx=\"32\" cy=\"32\" r=\"27\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\"/><path fill=\"currentColor\" d=\"M18 14l7-4 6 3 3 5 5 1 3 5-4 3-6-1-3 4-5-2-2 5-6-2-4-6 6-11zm24 20l6 3 3 7-4 7-7 3-2-6-5-2 1-7 8-5zM17 38l6 2 2 7-4 5-6-5 2-9z\"/></svg>`,color:'#25EFA0'}\n};\n\nfunction show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active')}\nfunction portrait(c){if(c?.portrait){return `<div class=\"portrait\"><img src=\"${esc(c.portrait)}\" alt=\"Illustration de ${esc(c.Philosophe)}\" onerror=\"this.style.display='none';this.nextElementSibling.style.display='grid'\"><div class=\"portrait-placeholder\" style=\"display:none\">ILLUSTRATION À AJOUTER<small>#${c.ID}</small></div></div>`}return `<div class=\"portrait\"><div class=\"portrait-placeholder\">ILLUSTRATION À AJOUTER<small>#${c?.ID||''}</small></div></div>`}\n$('rulesBtn').onclick=()=>$('rulesDialog').showModal();$('closeRules').onclick=()=>$('rulesDialog').close();document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>show(b.dataset.screen));$('createBtn').onclick=()=>show('create');$('joinBtn').onclick=()=>show('join');\n$('confirmCreate').onclick=()=>socket.emit('createRoom',{name:$('hostName').value,mode:$('gameMode').value,maxPlayers:+$('maxPlayers').value,ubermensch:$('ubermensch').checked});$('confirmJoin').onclick=()=>socket.emit('joinRoom',{code:$('roomCodeInput').value,name:$('joinName').value});socket.on('identity',x=>{identity=x;localStorage.setItem('philoIdentityV2',JSON.stringify(x))});socket.on('errorMessage',m=>alert(m));if(identity)socket.emit('reconnectRoom',identity);\nsocket.on('state',s=>{const was=state?.phase;state=s;CATS=s.config?.categories||CATS;render();});\nfunction render(){if(!state)return;if(state.status==='lobby'){show('lobby');renderLobby()}else if(state.status==='playing'){show('game');renderGame()}else if(state.status==='finished'){const w=state.players.find(p=>p.id===state.winnerId);$('winnerName').textContent=w?.name||'—';show('winner')}}\nfunction renderLobby(){$('roomCode').textContent=state.code;$('modeLabel').textContent=(state.mode==='superblind'?'Mode Super aveugle':(state.mode==='blind'?'Mode à l’aveugle':'Mode classique'))+(state.ubermensch?' · Übermensch':'');$('playerList').innerHTML=state.players.map(p=>`<div class=\"player-row\"><b>${esc(p.name)}</b><span>${p.isHost?'Hôte':''}${p.id===state.me.id?' · Vous':''}</span></div>`).join('');$('lobbyStatus').textContent=state.canStart?`${state.players.length} joueurs prêts.`:(state.me.id===state.players.find(p=>p.isHost)?.id?'En attente d’au moins un autre joueur…':'En attente du lancement par l’hôte…');$('startOnlineGame').classList.toggle('hidden',!state.canStart)}\n$('copyCode').onclick=async()=>{await navigator.clipboard?.writeText(state?.code||'');$('copyCode').textContent='COPIÉ !';setTimeout(()=>$('copyCode').textContent='COPIER LE CODE',1000)};$('startOnlineGame').onclick=()=>socket.emit('startGame');\nfunction renderGame(){\nconst leader=state.players.find(p=>p.id===state.leaderId);$('turnLabel').textContent='Tour '+state.round;$('leaderLabel').textContent='Leader : '+(leader?.name||'—');$('potLabel').textContent='Cagnotte : '+state.potCount;\n$('scoreboard').innerHTML=state.players.map(p=>`<div class=\"score-chip ${p.id===state.me.id?'me':''}\">${esc(p.name)} · ${p.cardCount}${state.ubermensch?' · ⚡'+p.powerCharges:''}${p.connected?'':' · hors ligne'}</div>`).join('');\nrenderTimer();renderPower();\nconst superBlind=state.mode==='superblind'&&state.phase==='choose'&&!state.rousseauActive;\n$('myCard').innerHTML=state.me.card?(superBlind?superBlindCardHtml(state.me.card):cardHtml(state.me.card)):'<div class=\"portrait-placeholder\">Vous n’avez plus de cartes.</div>';\nif(state.phase==='choose'){$('waitingChoice').classList.remove('hidden');$('revealBox').classList.add('hidden');\n const forced=state.forcedCategory&&!state.forcedOverrideThisRound; $('phaseMessage').textContent=forced?`Catégorie imposée : ${state.forcedCategory}`:(state.canChoose?'Choisissez une catégorie.':`En attente du choix de ${leader?.name||'leader'}…`);\n $('categoryButtons').innerHTML=CATS.map(cat=>categoryButton(cat,state.me.card,state.canChoose&&!forced,superBlind)).join('');\n document.querySelectorAll('.cat-btn').forEach(b=>b.onclick=()=>socket.emit('chooseCategory',b.dataset.cat));\n renderOwnCategory();\n}else{$('waitingChoice').classList.add('hidden');$('revealBox').classList.remove('hidden');renderReveal()}}\nfunction renderTimer(){clearInterval(timerTick);const el=$('timerLabel');if(!state||state.phase!=='choose'||!state.deadline){el.textContent='—';el.classList.remove('urgent');return}const go=()=>{const n=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));el.textContent=n;el.classList.toggle('urgent',n<=2)};go();timerTick=setInterval(go,150)}\nfunction renderPower(){const pp=$('powerPanel'),eb=$('effectBanner'),pc=$('powerChoice'),peek=$('peekPanel');pp.classList.toggle('hidden',!state.ubermensch);eb.classList.add('hidden');pc.classList.add('hidden');peek.classList.add('hidden');if(!state.ubermensch)return;\n pp.innerHTML=`<div class=\"power-head\"><b>ÜBERMENSCH</b><span class=\"charges\">${'⚡'.repeat(state.me.powerCharges)}${'·'.repeat(Math.max(0,3-state.me.powerCharges))}</span></div><div class=\"status-effects\">${esc((state.statusEffects||[]).join(' · '))}</div>`+(state.canUsePower?'<button id=\"usePowerBtn\" class=\"power-btn\" aria-label=\"Jouer l\\'atout\" title=\"Jouer l\\'atout\">⚡</button><div class=\"power-hint\">ATOUT — cliquez pour le révéler et le jouer</div>':(state.me.hasPower&&state.me.powerCharges<=0?'<div class=\"muted\">Cette carte possède un atout, mais vous n’avez plus de charge.</div>':(state.me.hasPower?'<div class=\"power-hint\">⚡ Cette carte possède un atout — utilisable lorsque vous êtes en attente.</div>':'')));\n if(state.canUsePower)$('usePowerBtn').onclick=()=>socket.emit('usePower');\n if(state.activePower){eb.classList.remove('hidden');eb.innerHTML=`<b>${esc(state.activePower.name)}</b> — ${esc(state.activePower.effect)} <small>(${esc(state.activePower.playerName)})</small>`}\n if(state.powerChoice?.type==='spinoza'){pc.classList.remove('hidden');pc.innerHTML='<b>Cause adéquate de ses actions</b><p>Choisissez votre carte pour le prochain tour :</p><div class=\"choice-cards\">'+state.powerChoice.options.map(o=>`<button class=\"choice-card\" data-cid=\"${o.id}\"><b>${esc(o.name)}</b><br><small>${esc(o.dates||'')}</small></button>`).join('')+'</div>';pc.querySelectorAll('button').forEach(b=>b.onclick=()=>socket.emit('chooseNextCard',+b.dataset.cid))}\n if(state.peekCards?.length){peek.classList.remove('hidden');peek.innerHTML='<b>Volonté de savoir</b>'+state.peekCards.map(x=>`<div class=\"peek-row\"><strong>${esc(x.player)}</strong>${CATS.map(c=>`<span>${x.scores[c]}</span>`).join('')}</div>`).join('')}\n}\nfunction renderOwnCategory(){let old=document.getElementById('ownCategory');if(old)old.remove();if(!state.me.canChooseOwnCategory||state.phase!=='choose')return;const d=document.createElement('div');d.id='ownCategory';d.className='own-cat';d.innerHTML='<b>Liberté individuelle :</b> choisissez votre propre statistique pour cette manche.<br>'+CATS.map(c=>`<button data-own=\"${esc(c)}\">${esc(c)}</button>`).join('');$('waitingChoice').prepend(d);d.querySelectorAll('button').forEach(b=>b.onclick=()=>socket.emit('chooseOwnCategory',b.dataset.own))}\nfunction categoryButton(cat,c,enabled,superBlind=false){const score=c?.[cat];const masked=score==null;if(superBlind)return `<button class=\"cat-btn\" data-cat=\"${esc(cat)}\" ${enabled?'':'disabled'}><span class=\"cat-icon\">${ICONS[cat]?.svg||'•'}</span><b class=\"cat-title\">${esc(cat)}</b></button>`;return `<button class=\"cat-btn\" data-cat=\"${esc(cat)}\" ${enabled?'':'disabled'}><span class=\"cat-icon\">${ICONS[cat]?.svg||'•'}</span><b class=\"cat-title\">${esc(cat)}</b><span class=\"cat-comment\">${esc(c?.['Commentaire '+cat]||'')}</span><em class=\"cat-score ${masked?'masked-score':''} ${state.rousseauActive?'fake-score':''}\">${masked?'00':score}</em></button>`}\nfunction cardHtml(c){return `${portrait(c)}<div class=\"identity\"><div class=\"identity-top\"><div><h1>${esc(c.Philosophe)}</h1><p class=\"dates\">${esc(c.Dates)}</p></div><div class=\"current\">${esc(c.Courant)}</div></div></div><div class=\"fact-grid\"><div class=\"fact\"><b>Pays</b><span>${esc(c.Pays)}</span></div><div class=\"fact\"><b>Œuvres</b><span>${esc(c['Œuvres'])}</span></div></div><blockquote class=\"quote\">« ${esc(c.Citation)} »<small>${esc(c['Source citation'])}</small></blockquote>`}\nfunction superBlindCardHtml(c){return `<div class=\"identity\" style=\"padding:24px 20px 4px\"><div class=\"eyebrow\" style=\"color:#8a652c\">SUPER AVEUGLE</div></div><blockquote class=\"quote\" style=\"margin-top:12px;font-size:1.28rem\">« ${esc(c.Citation)} »</blockquote><div class=\"fact-grid\" style=\"padding-bottom:26px\"><div class=\"fact\"><b>Fait marquant</b><span>${esc(c['Fait marquant']||'—')}</span></div></div>`}\nfunction renderReveal(){const r=state.reveal;if(!r)return;$('revealTitle').textContent=r.category;$('phaseMessage').textContent='Les scores sont révélés.';$('revealGrid').innerHTML=r.entries.map(e=>{const p=state.players.find(x=>x.id===e.pid);return `<div class=\"reveal-card ${r.winners.includes(e.pid)?'winner':''}\"><b>${esc(p?.name||'')}</b><span>${esc(e.philosopher)}</span><strong>${e.score==null?'?':e.score}</strong></div>`}).join('');$('roundResult').textContent=r.winners.length===1?`${state.players.find(p=>p.id===r.winners[0])?.name||''} remporte le pli.`:`Égalité entre ${r.winners.map(id=>state.players.find(p=>p.id===id)?.name).join(', ')}.`;$('nextRound').classList.toggle('hidden',!state.canAdvance);$('nextRound').textContent=r.winners.length===1?'ATTRIBUER LE PLI':'CONTINUER L’ÉGALITÉ'}\n$('nextRound').onclick=()=>{playStartSound();socket.emit('nextRound')};function leave(){socket.emit('leaveRoom');localStorage.removeItem('philoIdentityV2');identity=null;state=null;show('home')}$('leaveLobby').onclick=leave;$('leaveGame').onclick=leave;$('winnerHome').onclick=leave;\n})();</script>\n</body></html>\n";

